import os
import queue
import threading
from dataclasses import dataclass
from typing import Iterator, Optional

import pyaudio
from google.cloud import speech


@dataclass
class TranscriptEvent:
    text: str
    is_final: bool


class StreamingSpeechToText:
    def __init__(
        self,
        rate: int = 16000,
        chunk: int = 1024,
        language_code: str = "en-US",
        interim_results: bool = True,
        microphone_index: Optional[int] = None,
    ):
        self.rate = rate
        self.chunk = chunk
        self.language_code = language_code
        self.interim_results = interim_results
        self.microphone_index = microphone_index

        self._audio_queue: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._stop_event = threading.Event()
        self._stream = None
        self._audio_interface = None

    def _audio_callback(self, in_data, frame_count, time_info, status_flags):
        if self._stop_event.is_set():
            return (None, pyaudio.paComplete)
        self._audio_queue.put(in_data)
        return (None, pyaudio.paContinue)

    def _request_generator(self):
        yield speech.StreamingRecognizeRequest(
            streaming_config=speech.StreamingRecognitionConfig(
                config=speech.RecognitionConfig(
                    encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
                    sample_rate_hertz=self.rate,
                    language_code=self.language_code,
                ),
                interim_results=self.interim_results,
                single_utterance=False,
            )
        )
        while not self._stop_event.is_set():
            data = self._audio_queue.get()
            if data is None:
                return
            yield speech.StreamingRecognizeRequest(audio_content=data)

    def start(self) -> Iterator[TranscriptEvent]:
        client = speech.SpeechClient()
        self._audio_interface = pyaudio.PyAudio()

        self._stream = self._audio_interface.open(
            format=pyaudio.paInt16,
            channels=1,
            rate=self.rate,
            input=True,
            frames_per_buffer=self.chunk,
            input_device_index=self.microphone_index,
            stream_callback=self._audio_callback,
        )

        self._stream.start_stream()

        try:
            responses = client.streaming_recognize(requests=self._request_generator())
            for response in responses:
                if self._stop_event.is_set():
                    break
                if not response.results:
                    continue
                result = response.results[0]
                if not result.alternatives:
                    continue
                text = result.alternatives[0].transcript.strip()
                if text:
                    yield TranscriptEvent(text=text, is_final=result.is_final)
        finally:
            self.stop()

    def stop(self):
        self._stop_event.set()
        try:
            self._audio_queue.put_nowait(None)
        except Exception:
            pass

        if self._stream is not None:
            if self._stream.is_active():
                self._stream.stop_stream()
            self._stream.close()
            self._stream = None

        if self._audio_interface is not None:
            self._audio_interface.terminate()
            self._audio_interface = None


def stream_microphone_transcripts(
    language_code: str = "en-US",
    rate: int = 16000,
    chunk: int = 1024,
    microphone_index: Optional[int] = None,
) -> Iterator[str]:
    recognizer = StreamingSpeechToText(
        language_code=language_code,
        rate=rate,
        chunk=chunk,
        microphone_index=microphone_index,
    )
    for event in recognizer.start():
        yield event.text
